/* РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚ Р В±Р В°Р В»Р В°Р Р…РЎРѓ РЎС“РЎР‚Р С•Р С”Р В° РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚РІвЂќР‚ */

/**
 * Р вЂ™ РЎвЂЎР В°РЎРѓРЎвЂљР С‘ РЎС“РЎР‚Р С•Р С”Р С•Р Р† Р В±РЎвЂ№Р В»Р С• Р С—Р С• 4РІР‚вЂњ5 Р С”Р В°РЎР‚РЎвЂљР С•РЎвЂЎР ВµР С” Р’В«РЎРѓР В°Р СР С•Р С—РЎР‚Р С•Р Р†Р ВµРЎР‚Р С”Р С‘Р’В» Р С‘ Р Р†РЎРѓР ВµР С–Р С• Р С•Р Т‘Р С‘Р Р…
 * Р Р†Р С•Р С—РЎР‚Р С•РЎРѓ: Р В·Р В°Р Р…РЎРЏРЎвЂљР С‘Р Вµ Р С—РЎР‚Р ВµР Р†РЎР‚Р В°РЎвЂ°Р В°Р В»Р С•РЎРѓРЎРЉ Р Р† РЎвЂЎРЎвЂљР ВµР Р…Р С‘Р Вµ РЎвЂљР ВµР С•РЎР‚Р С‘Р С‘. Р С›РЎРѓРЎвЂљР В°Р Р†Р В»РЎРЏР ВµР С Р Р…Р Вµ Р В±Р С•Р В»РЎРЉРЎв‚¬Р Вµ
 * Р Т‘Р Р†РЎС“РЎвЂ¦ РЎвЂљР В°Р С”Р С‘РЎвЂ¦ Р С”Р В°РЎР‚РЎвЂљР С•РЎвЂЎР ВµР С” Р Р…Р В° РЎС“РЎР‚Р С•Р С”, Р С•РЎРѓРЎвЂљР В°Р В»РЎРЉР Р…РЎвЂ№Р Вµ Р С—РЎР‚Р ВµР Р†РЎР‚Р В°РЎвЂ°Р В°Р ВµР С Р Р† Р Р†Р С•Р С—РЎР‚Р С•РЎРѓРЎвЂ№ РЎРѓ
 * Р Р†Р В°РЎР‚Р С‘Р В°Р Р…РЎвЂљР В°Р СР С‘. Р вЂќР С‘РЎРѓРЎвЂљРЎР‚Р В°Р С”РЎвЂљР С•РЎР‚РЎвЂ№ Р В±Р ВµРЎР‚РЎвЂР С Р С‘Р В· Р С•РЎвЂљР Р†Р ВµРЎвЂљР С•Р Р† Р Т‘РЎР‚РЎС“Р С–Р С‘РЎвЂ¦ Р С”Р В°РЎР‚РЎвЂљР С•РЎвЂЎР ВµР С” Р Р…Р В°Р Р†РЎвЂ№Р С”Р В° РІР‚вЂќ
 * Р С•Р Р…Р С‘ Р Р† РЎвЂљР ВµР СР Вµ Р С‘ Р Р…Р Вµ Р Р†РЎвЂ№Р Т‘Р В°РЎР‹РЎвЂљ Р С—РЎР‚Р В°Р Р†Р С‘Р В»РЎРЉР Р…РЎвЂ№Р в„– Р Р†Р В°РЎР‚Р С‘Р В°Р Р…РЎвЂљ.
 */
function balanceLessons() {
  for (const skill of SKILLS) {
    for (const lesson of skill.lessons) {
      const flips = lesson.cards.filter((c) => !c.type);
      /* трогаем только уроки, где вопросов почти нет: если интерактива
         и так достаточно, теорию не трогаем */
      if (flips.length <= 2 || lesson.cards.length - flips.length >= 4) continue;

      /* РЎРЅР°С‡Р°Р»Р° Р±РµСЂС‘Рј РѕС‚РІРµС‚С‹ СЌС‚РѕРіРѕ Р¶Рµ СѓСЂРѕРєР°: РѕРЅРё РѕР± РѕРґРЅРѕРј Рё С‚РѕРј Р¶Рµ,
         РїРѕСЌС‚РѕРјСѓ Рё РІС‹РіР»СЏРґСЏС‚ РєР°Рє РїСЂР°РІРґРѕРїРѕРґРѕР±РЅС‹Рµ РІР°СЂРёР°РЅС‚С‹. */
      const localPool = lesson.cards
        .filter((c) => !c.type && typeof c.a === 'string')
        .map((c) => c.a);

      let toConvert = flips.length - 2;
      for (const card of lesson.cards) {
        if (toConvert <= 0) break;
        if (card.type || typeof card.a !== 'string') continue;

        const answer = card.a;
        const opts = [answer];
        for (const candidate of localPool) {
          if (opts.length >= 4) break;
          if (candidate === answer || opts.includes(candidate)) continue;
          opts.push(candidate);
        }
        if (opts.length < 3) continue;

        /* Р С—РЎР‚Р В°Р Р†Р С‘Р В»РЎРЉР Р…РЎвЂ№Р в„– Р Р†Р В°РЎР‚Р С‘Р В°Р Р…РЎвЂљ Р Р…Р Вµ Р Т‘Р С•Р В»Р В¶Р ВµР Р… Р Р†РЎРѓР ВµР С–Р Т‘Р В° РЎРѓРЎвЂљР С•РЎРЏРЎвЂљРЎРЉ Р С—Р ВµРЎР‚Р Р†РЎвЂ№Р С */
        const shift = card.q.length % opts.length;
        const options = opts.slice(shift).concat(opts.slice(0, shift));

        card.type = 'choice';
        card.options = options;
        card.a = options.indexOf(answer);
        card.explain = card.hint || '';
        delete card.hint;
        toConvert--;
      }
    }
  }
}

balanceLessons();
